#include "../src/hsd_scene.h"
#include <stdio.h>
#include <math.h>
static void dump(Melee360Scene s,const char* name){for(unsigned int b=0;b<s.batches.size();++b)for(unsigned int v=0;v<s.batches[b].vertices.size();++v){Melee360SceneVertex& o=s.batches[b].vertices[v];o.clip[0]=o.clip[0]*.65f-.4f;o.clip[1]=o.clip[1]*.65f-.05f;o.clip[2]=.5f+o.clip[2]*.1f;}char path[128];sprintf(path,"%s.bin",name);FILE* f=fopen(path,"wb");unsigned int n=(unsigned int)s.textures.size();fwrite(&n,4,1,f);for(unsigned int i=0;i<n;++i){Melee360SceneTexture& t=s.textures[i];fwrite(&t.width,4,1,f);fwrite(&t.height,4,1,f);fwrite(&t.pixels[0],4,t.width*t.height,f);}n=(unsigned int)s.batches.size();fwrite(&n,4,1,f);for(unsigned int i=0;i<n;++i){Melee360SceneBatch& b=s.batches[i];unsigned int count=(unsigned int)b.vertices.size();fwrite(&b.texture,4,1,f);fwrite(&b.mode,4,1,f);fwrite(&b.wrapS,4,1,f);fwrite(&b.wrapT,4,1,f);fwrite(&count,4,1,f);fwrite(&b.vertices[0],sizeof(Melee360SceneVertex),count,f);}fclose(f);}
int main(){const char* files[]={"TyDaisy.dat","TyKusuda.dat","TyStand.dat"};const char* names[]={"ToyDaisyModel_TopN_joint","ToyKusudamaModel_TopN_joint","ToyStandModel_TopN_joint"};for(int i=0;i<3;++i){char path[512];sprintf(path,"C:\\Users\\luizf\\Documents\\melee_extraido\\%s",files[i]);FILE* f=fopen(path,"rb");if(!f)return 1;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);std::vector<unsigned char> d(n);if(fread(&d[0],1,n,f)!=(size_t)n)return 2;fclose(f);Melee360ResetSceneCache();Melee360Scene s;if(!Melee360LoadTrophyModel(&d[0],n,names[i],s))return 3;unsigned int count=0;for(unsigned int b=0;b<s.batches.size();++b)for(unsigned int v=0;v<s.batches[b].vertices.size();++v){++count;for(int c=0;c<4;++c)if(!_finite(s.batches[b].vertices[v].clip[c]))return 4;}if(!count||s.textures.empty())return 5;printf("%s: %u vertices, %u textures, skipped=%u\n",files[i],count,(unsigned int)s.textures.size(),s.skipped);dump(s,files[i]);if(Melee360LoadTrophyModel(&d[0],n-1,names[i],s))return 6;}puts("Trophy original model geometry and truncation tests passed");return 0;}
